<script setup>
import {computed,onMounted,onBeforeUnmount,ref,reactive} from 'vue';
import {useApp} from '../stores/app';import api from '../services/api';import SeleccionarLocal from '../components/SeleccionarLocal.vue';
const s=useApp(),pedidos=ref([]),edicao=ref(null),quantidade=ref(0),preco=ref(0),erro=ref(''),busy=ref(false),editarFarmacia=ref(false);
const farm=computed(()=>s.farmacias.find(f=>f.id===s.utilizador?.farmaciaId));
const detalhes=reactive({nomeFarmacia:'',bairro:'',endereco:'',telefone:'',horario:'',lat:null,lng:null});
const linhas=computed(()=>s.medicamentos.map(m=>({med:m,stock:s.stock.find(x=>x.farmaciaId===s.utilizador?.farmaciaId&&x.medicamentoId===m.id)})));
const meusPedidos=computed(()=>pedidos.value.filter(x=>x.farmaciaId===s.utilizador?.farmaciaId));
const labels={aguarda_pagamento:'Aguarda pagamento',confirmado:'Confirmado',em_preparacao:'Em preparação',em_entrega:'Em entrega',pronto_recolha:'Pronto para recolha',entregue:'Entregue',cancelado:'Cancelado'};
async function carregar(){try{pedidos.value=(await api.get('/pedidos')).data;await s.carregar();}catch(e){erro.value=e.message;}}
function editar(x){edicao.value=x;quantidade.value=x.stock?.quantidade??0;preco.value=x.stock?.preco??0;}
async function guardar(){busy.value=true;erro.value='';try{await api.put(`/meu-stock/${edicao.value.med.id}`,{quantidade:Number(quantidade.value),preco:Number(preco.value),versao:edicao.value.stock?.versao});edicao.value=null;await carregar();}catch(e){erro.value=e.message;await carregar();}finally{busy.value=false;}}
function abrirDados(){Object.assign(detalhes,{nomeFarmacia:farm.value.nome,bairro:farm.value.bairro,endereco:farm.value.endereco,telefone:farm.value.telefone,horario:farm.value.horario,lat:farm.value.lat,lng:farm.value.lng});editarFarmacia.value=true;}
async function guardarFarmacia(){busy.value=true;erro.value='';try{await api.put('/minha-farmacia',{...detalhes});editarFarmacia.value=false;await carregar();}catch(e){erro.value=e.message;}finally{busy.value=false;}}
async function avancar(p){const proximo={confirmado:'em_preparacao',em_preparacao:p.tipoEntrega==='entrega'?'em_entrega':'pronto_recolha',em_entrega:'entregue',pronto_recolha:'entregue'}[p.estado];if(!proximo)return;try{await api.patch(`/pedidos/${p.id}/estado`,{estado:proximo});await carregar();}catch(e){erro.value=e.message;}}
const refresh=()=>carregar();onMounted(()=>{carregar();window.addEventListener('fr:refresh',refresh);});onBeforeUnmount(()=>window.removeEventListener('fr:refresh',refresh));
</script>
<template><div class="container page"><div class="page-heading"><div><h1>Gestão da farmácia</h1><p>{{farm?.nome||'A sua farmácia'}}</p></div><button class="button outline-button" v-if="farm" @click="abrirDados">Dados e localização</button></div>
<div v-if="erro" class="alert error">{{erro}}</div>
<div class="stats-grid"><div class="stat-card"><small>Medicamentos no catálogo</small><strong>{{linhas.length}}</strong></div><div class="stat-card"><small>Em stock</small><strong>{{linhas.filter(x=>x.stock?.quantidade>0).length}}</strong></div><div class="stat-card"><small>Encomendas recebidas</small><strong>{{meusPedidos.length}}</strong></div></div>
<div class="panel admin-table"><div class="panel-title"><h3>Stock e preços</h3></div><div class="table-scroll"><table><thead><tr><th>Medicamento</th><th>Quantidade</th><th>Preço</th><th>Acção</th></tr></thead><tbody><tr v-for="x in linhas" :key="x.med.id"><td>{{x.med.nome}} · {{x.med.dosagem}}</td><td>{{x.stock?.quantidade??0}}</td><td>{{x.stock?`${x.stock.preco} MT`:'Por definir'}}</td><td><button class="text-action" @click="editar(x)">{{x.stock?'Editar':'Adicionar stock'}}</button></td></tr></tbody></table></div></div>
<div class="panel admin-orders"><h3>Encomendas</h3><p v-if="!meusPedidos.length">Ainda não há encomendas.</p><div class="admin-order-row" v-for="p in meusPedidos" :key="p.id"><div><b>#{{p.id.slice(0,8).toUpperCase()}} · {{p.clienteNome}}</b><small>{{p.total.toFixed(2)}} MT · {{p.tipoEntrega==='entrega'?'Entrega':'Recolha'}}</small></div><span>{{labels[p.estado]||p.estado}}</span><button class="button button-small primary" v-if="['confirmado','em_preparacao','em_entrega','pronto_recolha'].includes(p.estado)" @click="avancar(p)">Avançar</button></div></div>
<div class="modal-backdrop" v-if="edicao" @click.self="edicao=null"><div class="modal"><h2>{{edicao.med.nome}}</h2><label class="field">Quantidade<input type="number" v-model.number="quantidade" min="0"/></label><label class="field">Preço (MT)<input type="number" v-model.number="preco" min="1" step="0.01"/></label><div class="modal-buttons"><button class="button outline-button" @click="edicao=null">Cancelar</button><button class="button primary" :disabled="busy" @click="guardar">Guardar</button></div></div></div>
<div v-if="editarFarmacia" class="modal-backdrop" @click.self="editarFarmacia=false"><div class="modal" style="max-width:650px;max-height:90vh;overflow:auto"><h2>Dados da farmácia</h2><form @submit.prevent="guardarFarmacia"><label class="field">Nome<input required v-model="detalhes.nomeFarmacia"/></label><label class="field">Telefone<input required v-model="detalhes.telefone"/></label><label class="field">Bairro<input required v-model="detalhes.bairro"/></label><label class="field">Endereço<input required v-model="detalhes.endereco"/></label><label class="field">Horário<input v-model="detalhes.horario"/></label><label>Localização no mapa</label><SeleccionarLocal :lat="detalhes.lat" :lng="detalhes.lng" @escolher="p=>{detalhes.lat=p.lat;detalhes.lng=p.lng}"/><div class="modal-buttons"><button type="button" class="button outline-button" @click="editarFarmacia=false">Cancelar</button><button class="button primary" :disabled="busy">Guardar</button></div></form></div></div>
</div></template>
